insert into public.reward_rules(
  platform_id,activity_id,event_type,trust_level,xp,points,coins,repeatable,active,metadata,updated_at
)
select p.id,'completion:'||s.id,'activity.completed','rule_validated',s.xp,0,s.coins,false,true,
  jsonb_build_object('source','lab-virtual-core','client_claimable',false,'validation','catalog+tool-open+minimum-time','catalogVersion','4.28.0'),now()
from p cross join seed s
on conflict (platform_id,(coalesce(activity_id,'*'::text)),event_type) do update set
  trust_level=excluded.trust_level,xp=excluded.xp,points=excluded.points,coins=excluded.coins,
  repeatable=false,active=true,metadata=excluded.metadata,updated_at=now();

-- First valid completion on a tool. Values are the original LABDS level bonuses.
with p as (select id from public.platforms where code='lab-virtual' and active=true limit 1),
seed(event_type,coins) as (values
  ('tool.first_validated.basic',15),
  ('tool.first_validated.intermediate',30),
  ('tool.first_validated.advanced',50)
)
